#include <queue>
#include <iostream>

int main() {
    std::priority_queue<int> pq;
    pq.push(10);

    // Correct processing pattern
    if (!pq.empty()) {
        int highest = pq.top(); // O(1) access
        std::cout << highest << "\n";
        pq.pop();               // O(log N) removal
    }

    // pq.top(); // DANGER: UB if called here (pq is empty)
}
